## master
 M .gitignore
* master
#!/bin/bash
. src/lib/slots.sh
fail=0
overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
[ "$(to_min 09:05)" = 545 ] || { echo "to_min 09:05"; fail=1; }
exit $fail

#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-02\t10:00\t11:00\tx\nkaede\t2026-01-01\t09:00\t10:00\ty\n' > "$t"
[ "$(BOOKINGS=$t bash src/list.sh | head -1)" = '2026-01-01 09:00-10:00 kaede y' ] || { echo "list sorted"; fail=1; }
[ "$(BOOKINGS=$t bash src/list.sh 2026-01-02)" = '2026-01-02 10:00-11:00 aoi x' ] || { echo "list by date"; fail=1; }
rm -f "$t"; exit $fail

./src/book.sh:12:  if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
./src/lib/slots.sh:4:# overlaps S1 E1 S2 E2 (minutes): succeeds when the two bookings share time.
./src/lib/slots.sh:5:overlaps() { [ "$1" -le "$4" ] && [ "$3" -le "$2" ]; }
./spec/slots.spec.sh:4:overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
./spec/slots.spec.sh:5:overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
./spec/slots.spec.sh:6:! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
