input.command:
cat > spec/slots.spec.sh <<'EOF'
#!/bin/bash
. src/lib/slots.sh
fail=0
overlaps 600 660 630 700 || { echo "overlap: 10:00-11:00 vs 10:30-11:40"; fail=1; }
overlaps 600 720 630 650 || { echo "overlap: containment"; fail=1; }
! overlaps 600 660 700 760 || { echo "apart: 10:00-11:00 vs 11:40-12:40"; fail=1; }
! overlaps 600 660 660 720 || { echo "adjacent: 10:00-11:00 then 11:00-12:00 must not overlap"; fail=1; }
! overlaps 660 720 600 660 || { echo "adjacent: 11:00-12:00 after 10:00-11:00 must not overlap"; fail=1; }
overlaps 600 661 660 720 || { echo "one-minute overlap must still overlap"; fail=1; }
[ "$(to_min 09:05)" = 545 ] || { echo "to_min 09:05"; fail=1; }
t=$(mktemp); : > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-11-12 10:00 11:00 sato >/dev/null
BOOKINGS=$t bash src/book.sh aoi 2026-11-12 11:00 12:00 ito >/dev/null 2>&1 || { echo "book: booking right after was refused"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-11-12 09:00 10:00 kato >/dev/null 2>&1 || { echo "book: booking right before was refused"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-11-12 10:30 11:30 x >/dev/null 2>&1 && { echo "book: overlapping booking was accepted"; fail=1; }
rm -f "$t"
exit $fail
EOF
bash tools/check
